INSERT INTO "QDATA"."ONL_DRAG_DATASET_HEAD"("id","name","code","parent_id","db_source","query_sql","content","iz_agent","data_type","api_method","create_time","create_by","update_time","update_by","low_app_id","tenant_id") VALUES('1516743766914924546','统计近十日的登陆次数','','1516743332632494082','1011872166805864448','SELECT
  count(*) num,
 DATE_FORMAT(create_time, ''%Y-%m-%d'') AS `day`
FROM
 sys_log
WHERE
  log_type = 1
AND create_time > DATE_SUB(NOW(), INTERVAL 10 DAY)
GROUP BY
  DATE_FORMAT(create_time, ''%Y-%m-%d'')','','','sql','get',TO_DATE('2022-04-20 19:41:08','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',TO_DATE('2024-10-31 15:51:02','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',null,1);
