INSERT INTO "QDATA"."ONL_DRAG_DATASET_HEAD"("id","name","code","parent_id","db_source","query_sql","content","iz_agent","data_type","api_method","create_time","create_by","update_time","update_by","low_app_id","tenant_id") VALUES('1517020649262972930','项目性质收入统计SQL','','1516743332632494082','1011872166805864448','SELECT
 id,
 nature,
 insurance_fee,
  risk_consulting_fee,
  evaluation_fee,
 insurance_evaluation_fee,
 bidding_consulting_fee,
 interol_consulting_fee,
 (
   insurance_fee + 
    risk_consulting_fee + 
    risk_consulting_fee + 
    evaluation_fee + 
   insurance_evaluation_fee + 
   bidding_consulting_fee + 
   interol_consulting_fee
  ) AS ''total''
FROM
  jeecg_project_nature_income','','','sql','get',TO_DATE('2022-04-21 14:01:22','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',TO_DATE('2024-10-31 15:51:07','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',null,1);
