INSERT INTO "QDATA"."ONL_DRAG_DATASET_HEAD"("id","name","code","parent_id","db_source","query_sql","content","iz_agent","data_type","api_method","create_time","create_by","update_time","update_by","low_app_id","tenant_id") VALUES('1522503560003067906','首页_近一周访问量','','1516743332632494082','1011872166805864448','select count(*) as visit
            ,count(distinct(ip)) as ip
            ,DATE_FORMAT(create_time, ''%Y-%m-%d'') as tian
             ,DATE_FORMAT(create_time, ''%m-%d'') as type
            from sys_log 
         where log_type = 1 and create_time <= sysdate() and create_time >= (select date_sub(curdate(),interval 7 day))
         group by tian,type
         order by tian desc','','0','sql','get',TO_DATE('2022-05-06 17:08:30','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',TO_DATE('2022-05-06 17:49:07','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',null,null);
