INSERT INTO "QDATA"."DA_ASSET"("ID","NAME","CAT_CODE","DATASOURCE_ID","TABLE_NAME","TABLE_COMMENT","DATA_COUNT","FIELD_COUNT","STATUS","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","SOURCE","TYPE","CREATE_TYPE") VALUES(1,'水资源水位数据（原始库）','A03A02','1','ods_wr_water_level','水资源水位原始明细',1000,6,'2','【Doris库、资产字段、资产预览、数据质量】外部系统采集的原始水位监测数据，字段保持源系统形态不做修改，主要用于数据质量溯源、原始备查。','1','0','吴同',2,TO_DATE('2025-09-19 17:04:05.797000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-19 17:04:09.178000','YYYY-MM-DD HH24:MI:SS.FF'),null,'3','1','2');
INSERT INTO "QDATA"."DA_ASSET"("ID","NAME","CAT_CODE","DATASOURCE_ID","TABLE_NAME","TABLE_COMMENT","DATA_COUNT","FIELD_COUNT","STATUS","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","SOURCE","TYPE","CREATE_TYPE") VALUES(2,'水资源测站点数据（原始库）','A03A02','1','ods_wr_water_level','水资源水位原始明细',1000,6,'1','【Doris库、资产字段、资产预览、数据质量】汇聚各外部系统（水资源管理、监测管理等）站点基础信息，字段原貌保存，支持跨源站点统一、后续维表加工。','1','1','吴同',2,TO_DATE('2025-09-19 17:06:40.008000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-19 17:22:06.142000','YYYY-MM-DD HH24:MI:SS.FF'),null,'3','1','2');
INSERT INTO "QDATA"."DA_ASSET"("ID","NAME","CAT_CODE","DATASOURCE_ID","TABLE_NAME","TABLE_COMMENT","DATA_COUNT","FIELD_COUNT","STATUS","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","SOURCE","TYPE","CREATE_TYPE") VALUES(3,'水文监测流量数据（原始库）','A03A01','1','ods_hyd_discharge','水文监测流量时序数据',1000,11,'2','【Doris库、资产字段、资产预览】接入水文监测平台的业务数据库，与第三方库数据保持一致，包含流量监测原始数据，用于水文计算、径流分析及防汛预警。','1','0','吴同',2,TO_DATE('2025-09-19 17:08:24.272000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-19 17:22:07.647000','YYYY-MM-DD HH24:MI:SS.FF'),null,'3','1','2');
