INSERT INTO "QDATA"."DA_SENSITIVE_LEVEL"("ID","SENSITIVE_LEVEl","SENSITIVE_RULE","START_CHAR_LOC","END_CHAR_LOC","MASK_CHARACTER","ONLINE_FLAG","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(2,'2级（机密）','1',null,null,'####','1','涉及水资源调度、水库运行、水源地保护、重要断面水质等关键业务数据，一旦泄露将影响行业管理和区域安全。','1','0','吴同',2,TO_DATE('2025-09-22 11:30:43.750000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 11:30:43.750000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."DA_SENSITIVE_LEVEL"("ID","SENSITIVE_LEVEl","SENSITIVE_RULE","START_CHAR_LOC","END_CHAR_LOC","MASK_CHARACTER","ONLINE_FLAG","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(3,'3级（秘密）','2',2,10,'****','1','涉及日常监测数据（如流量、水位、雨量等明细）、取水户用水记录、内部分析报表等，一旦泄露会对业务管理和内部运行造成不利影响。保留前3位，其余用***替代（如“孙燕姿”→“孙***”）','1','0','吴同',2,TO_DATE('2025-09-22 11:31:04.803000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 11:31:04.803000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."DA_SENSITIVE_LEVEL"("ID","SENSITIVE_LEVEl","SENSITIVE_RULE","START_CHAR_LOC","END_CHAR_LOC","MASK_CHARACTER","ONLINE_FLAG","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(4,'4级（内部）','2',3,8,'****','1','一般内部使用数据，如运维日志、调度流程记录、一般统计数据等，泄露影响较小但仍需内部保护。脱敏处理部分关键字段，如手机号138****5678','1','0','吴同',2,TO_DATE('2025-09-22 11:34:28.305000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 11:34:28.305000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."DA_SENSITIVE_LEVEL"("ID","SENSITIVE_LEVEl","SENSITIVE_RULE","START_CHAR_LOC","END_CHAR_LOC","MASK_CHARACTER","ONLINE_FLAG","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(5,'5级（公开）','1',null,null,'****','1','可以对外公开的数据，如水雨情简报、已公开的监测站点水质年报、宣传类信息等，不涉及安全和隐私。可直接展示或仅弱化部分敏感字段（如展示省、市，不展示精确坐标）','1','0','吴同',2,TO_DATE('2025-09-22 11:34:54.257000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 11:34:54.257000','YYYY-MM-DD HH24:MI:SS.FF'),null);

