NOT EXISTS hyd_water_level_spark_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level_spark'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- 3) 全量复制（保留 id）\r\nINSERT INTO hyd_water_level_spark_jdbc\r\nSELECT\r\n  id,\r\n  station_code,\r\n  sensor_id,\r\n  obs_time,\r\n  obs_date,\r\n  water_level_m,\r\n  quality_code,\r\n  source,\r\n  trace_id,\r\n  ext_json,\r\n  created_at\r\nFROM hyd_water_level_src;\r\n"}','2',0,1,0,-1,-1,'6',95,94,'1','0',null,null,TO_DATE('2025-09-22 17:02:23.448000','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-09-22 17:02:23.715000','YYYY-MM-DD HH24:MI:SS.FF'),null,'53');
