ter_level_spark_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level_spark'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- 3) 全量复制（保留 id）\r\nINSERT INTO hyd_water_level_spark_jdbc\r\nSELECT\r\n  id,\r\n  station_code,\r\n  sensor_id,\r\n  obs_time,\r\n  obs_date,\r\n  water_level_m,\r\n  quality_code,\r\n  source,\r\n  trace_id,\r\n  ext_json,\r\n  created_at\r\nFROM hyd_water_level_src;\r\n","executeMode":""}','2',0,1,0,-1,-1,'6',96,95,'1','0',null,null,TO_DATE('2025-09-22 17:03:44.564000','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-09-22 17:03:44.712000','YYYY-MM-DD HH24:MI:SS.FF'),null,'53');
INSERT INTO "QDATA"."DPP_ETL_NODE_INSTANCE"("ID","TASK_TYPE","NAME","NODE_TYPE","NODE_ID","NODE_CODE","NODE_VERSION","TASK_INSTANCE_ID","TASK_INSTANCE_NAME","PROJECT_ID","PROJECT_CODE","SUBMIT_TIME","START_TIME","END_TIME","EXECUTE_PATH","LOG_PATH","PARAMETERS","PRIORITY","RETRY_TIMES","FRETRY_INTERVAL","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","STATUS","DS_ID","DS_TASK_INSTANCE_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(97,'3','SparkSQL_水位日统计报表','SPARK',79,'152667889198400',3,96,'SparkSQL_水位日统计报表-3-20250922171828442',1,'152317790975712',TO_DATE('2025-09-22 17:18:28.000000','YYYY-MM-DD HH24:MI:SS.FF'),TO_DATE('2025-09-22 17:18:28.000000','YYYY-MM-DD HH24:MI:SS.FF'),TO_DATE('2025-09-22 17:18:28.000000','YYYY-MM-DD HH24:MI:SS.FF'),'/tmp/dolphinscheduler/exec/process/root/152317790975712/152667889198400_3/96/97','/opt/dolphinscheduler/logs/20250922/152667889198400/3/96/97.log','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":0,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"SparkSql","datasourceId":"","sqlType":"0","taskType":"SPARK","segm":"","componentType":"53","localParams":[],"sql":"-- ========== 1) 源：MySQL 水位明细 ==========\r\nCREATE TEMPORARY VIEW hyd_water_level_src\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\r\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\r\nCREATE TEMPORARY VIEW hyd_station_dim\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_station'',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''dws_station_water_day_report'',\r\n  user ''root'',\r\n  password ''InC3tmU4bijT4vkl'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\r\nWITH base AS (\r\n  SELECT\r\n    wl.station_code,\r\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\r\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\r\n  FROM hyd_water_level_src wl\r\n  WHERE wl.water_level_m IS NOT NULL\r\n),\r\nday_avg AS (\r\n  SELECT\r\n    station_code,\r\n    stat_date,\r\n    AVG(water_level_m) AS avg_level_day\r\n  FROM base\r\n  GROUP BY station_code, stat_date\r\n)\r\n\r\nINSERT INTO dws_station_water_day_report_jdbc\r\nSELECT\r\n  -- station_id：有维表用维表，没有则置 NULL\r\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\r\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\r\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\r\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\r\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\r\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\r\nFROM day_avg d\r\nLEFT JOIN hyd_station_dim s\r\n  ON s.station_code = d.station_code;","executeMode":""}','2',0,1,0,-1,-1,'6',97,96,'1','0',null,null,TO_DATE('2025-09-22 17:18:28.493000','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-09-22 17:18:28.828000','YYYY-MM-DD HH24:MI:SS.FF'),null,'53');
