r\nCREATE TABLE hyd_water_level_sink (\r\n    id             BIGINT,\r\n    station_code   STRING,\r\n    PRIMARY KEY (id) NOT ENFORCED\r\n) WITH (\r\n    ''connector'' = ''jdbc'',\r\n    ''url''       = ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&serverTimezone=Asia/Shanghai'',\r\n    ''table-name''= ''hyd_water_level_stream'',\r\n    ''username''  = ''root'',\r\n    ''password''  = ''sfdjfFF#s2332'',\r\n    ''sink.buffer-flush.max-rows'' = ''500'',\r\n    ''sink.buffer-flush.interval'' = ''2s'',\r\n    ''sink.max-retries'' = ''3''\r\n);\r\n\r\nINSERT INTO hyd_water_level_sink\r\nSELECT\r\n    id,\r\n    station_code\r\nFROM hyd_water_level_src;","executeMode":"STREAM"}','2',0,1,0,-1,-1,'7',98,97,'1','0',null,null,TO_DATE('2025-09-22 17:25:56.253000','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-09-22 17:26:11.853000','YYYY-MM-DD HH24:MI:SS.FF'),null,'55');
