			"querySql":"SELECT\n  s.\"BASIN_CODE\"                                   AS basin_code,\n  r.\"STAT_MONTH\"                                   AS stat_month,\n  COUNT(DISTINCT s.\"STATION_ID\")                   AS station_cnt,     \n  ROUND(AVG(TO_NUMBER(NULLIF(r.\"AVG_WATER_LEVEL\", ''''))), 3) AS avg_level, \n  ROUND(MAX(TO_NUMBER(NULLIF(r.\"AVG_WATER_LEVEL\", ''''))), 3) AS max_level,\n  ROUND(MIN(TO_NUMBER(NULLIF(r.\"AVG_WATER_LEVEL\", ''''))), 3) AS min_level\nFROM \"WATER_TP\".\"STATION\" s\nJOIN \"WATER_TP\".\"STATION_WATER_MONTH_REPORT\" r\n  ON r.\"STATION_ID\" = s.\"STATION_ID\"\n-- 如需过滤月份，可加：WHERE r.\"STAT_MONTH\" BETWEEN ''2025-01'' AND ''2025-12''\nGROUP BY\n  s.\"BASIN_CODE\",\n  r.\"STAT_MONTH\"\nORDER BY\n  r.\"STAT_MONTH\",\n  s.\"BASIN_CODE\"",
			"jdbcUrl":"jdbc:dm://dm8-demo:5236?schema=WATER_TP"
		},
		"batchSize":"1024",
		"readModeType":1,
		"username":"WATER_TP"
	},
	"nodeVersion":1
}
