  "taskInstanceId" : 65,
  "taskName" : "Flink流_水位信息采集",
  "firstSubmitTime" : 1758524356415,
  "startTime" : 1758524356447,
  "taskType" : "FLINK",
  "workflowInstanceHost" : "172.28.0.11:5678",
  "host" : "172.28.0.17:1234",
  "logPath" : "/opt/dolphinscheduler/logs/20250922/152659477902656/2/65/65.log",
