  "executorId" : 1,
  "cmdTypeIfComplement" : 0,
  "tenantCode" : "default",
  "processDefineId" : 0,
  "projectId" : 0,
  "projectCode" : 152317790975712,
  "taskParams" : "{\"localParams\":[],\"rawScript\":\"-- ========= 1) 源表：MySQL (hyd.hyd_water_level)  =========\\r\\nCREATE TABLE src_hyd_water_level (\\r\\n  id              BIGINT,              -- MySQL: bigint(20) unsigned AUTO_INCREMENT\\r\\n  station_code    STRING,\\r\\n  sensor_id       BIGINT,\\r\\n  obs_time        TIMESTAMP(3),        -- MySQL: datetime\\r\\n  obs_date        DATE,                -- MySQL: date\\r\\n  water_level_m   DECIMAL(10,3),\\r\\n  quality_code    STRING,\\r\\n  source          STRING,\\r\\n  trace_id        STRING,\\r\\n  ext_json        STRING,              -- MySQL: text -> 以 STRING 读取\\r\\n  created_at      TIMESTAMP(3),        -- MySQL: timestamp\\r\\n  PRIMARY KEY (id) NOT ENFORCED\\r\\n) WITH (\\r\\n  ''connector'' = ''mysql-cdc'',\\r\\n  ''hostname''  = ''mysql57'',\\r\\n  ''port''      = ''3306'',\\r\\n  ''username''  = ''root'',\\r\\n  ''password''  = ''sfdjfFF#s2332'',\\r\\n  ''database-name'' = ''hydrology'',\\r\\n  ''table-name''    = ''hyd_water_level'',\\r\\n  -- 建议设置时区，避免时间字段偏移\\r\\n  ''server-time-zone'' = ''Asia/Shanghai'',\\r\\n  -- 开启增量快照，首跑更稳\\r\\n  ''scan.incremental.snapshot.enabled'' = ''true''\\r\\n);\\r\\n\\r\\n-- ========= 2) 目标表：Doris (ods.ods_hyd_water_level_flink_stream) =========\\r\\n-- 说明：与你给的 Doris 目标表字段/顺序一致（id → created_at）\\r\\nCREATE TABLE sink_ods_hyd_water_level_flink_stream (\\r\\n  id             BIGINT         COMMENT ''自增主键'',\\r\\n  station_code   VARCHAR(64)    COMMENT ''站点编码（软关联）'',\\r\\n  sensor_id      BIGINT         COMMENT ''传感器ID（软关联）'',\\r\\n  obs_time       TIMESTAMP(3)   COMMENT ''观测时间'',          -- Doris: DATETIME，Flink 写入 TIMESTAMP(3) OK\\r\\n  obs_date       DATE           COMMENT ''观测日期'',\\r\\n  water_level_m  DECIMAL(10,3)  COMMENT ''水位(米)'',\\r\\n  quality_code   VARCHAR(16)    COMMENT ''质量代码'',\\r\\n  source         VARCHAR(64)    COMMENT ''来源'',\\r\\n  trace_id       VARCHAR(64)    COMMENT ''追踪ID/批次号'',\\r\\n  ext_json       STRING         COMMENT ''扩展字段（原 JSON）'', -- Doris TEXT 也可接收；用 STRING 写入最通用\\r\\n  created_at     TIMESTAMP(3)   COMMENT ''创建时间''\\r\\n) WITH (\\r\\n  ''connector'' = ''doris'',\\r\\n  -- Doris FE http 端口（一般 8030）\\r\\n  ''fenodes'' = ''host.docker.internal:8030'',\\r\\n  -- JDBC URL（建议指向 9030）\\r\\n  ''jdbc-url'' = ''jdbc:mysql://host.docker.internal:9030'',\\r\\n  -- 目标库表\\r\\n  ''table.identifier'' = ''ods.ods_hyd_water_level_flink_stream'',\\r\\n  ''username'' = ''root'',\\r\\n  ''password'' = ''InC3tmU4bijT4vkl'',\\r\\n\\r\\n  -- 写入可靠性与吞吐\\r\\n  ''sink.enable-2pc'' = ''true'',\\r\\n  ''sink.label-prefix'' = ''flink_hwl'',\\r\\n  ''sink.max-retries'' = ''3'',\\r\\n  ''sink.buffer-flush.max-rows'' = ''5000'',\\r\\n  ''sink.buffer-flush.interval'' = ''5s'',\\r\\n\\r\\n  -- 建议用 JSON 格式（对 TEXT/STRING 友好）\\r\\n  ''sink.properties.format'' = ''json'',\\r\\n  ''sink.properties.read_json_by_line'' = ''true'',\\r\\n  -- 可选：严格过滤\\r\\n  ''sink.properties.max_filter_ratio'' = ''0''\\r\\n);\\r\\n\\r\\n-- ========= 3) 实时同步（Upsert 语义由 CDC + Doris Sink 保证） =========\\r\\nINSERT INTO sink_ods_hyd_water_level_flink_stream\\r\\nSELECT\\r\\n  id,\\r\\n  CAST(station_code AS VARCHAR(64))         AS station_code,\\r\\n  sensor_id,\\r\\n  obs_time,\\r\\n  obs_date,\\r\\n  water_level_m,\\r\\n  CAST(quality_code AS VARCHAR(16))         AS quality_code,\\r\\n  CAST(source AS VARCHAR(64))               AS source,\\r\\n  CAST(trace_id AS VARCHAR(64))             AS trace_id,\\r\\n  ext_json,                                 -- 保持原样（STRING）\\r\\n  created_at\\r\\nFROM src_hyd_water_level;\",\"resourceList\":[],\"programType\":\"SQL\",\"mainClass\":\"\",\"deployMode\":\"local\",\"yarnQueue\":\"\",\"flinkVersion\":\">=1.13\",\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"initScript\":\"\"}",
  "environmentConfig" : "export FLINK_HOME=/opt/soft/flink\nexport SPARK_HOME=/opt/soft/spark\nexport DATAX_LAUNCHER=/opt/soft/datax/bin/datax.py\nexport PYTHON_LAUNCHER=/usr/bin/python3\nexport JAVA_HOME=/opt/java/openjdk\nexport PATH=$FLINK_HOME/bin:$SPARK_HOME/bin:$PYTHON_LAUNCHER:$JAVA_HOME/bin:$DATAX_LAUNCHER:$PATH",
