-- ========= 1) 源表：MySQL (hyd.hyd_water_level)  =========
CREATE TABLE src_hyd_water_level (
  id              BIGINT,              -- MySQL: bigint(20) unsigned AUTO_INCREMENT
  station_code    STRING,
  sensor_id       BIGINT,
  obs_time        TIMESTAMP(3),        -- MySQL: datetime
  obs_date        DATE,                -- MySQL: date
  water_level_m   DECIMAL(10,3),
  quality_code    STRING,
  source          STRING,
  trace_id        STRING,
  ext_json        STRING,              -- MySQL: text -> 以 STRING 读取
  created_at      TIMESTAMP(3),        -- MySQL: timestamp
  PRIMARY KEY (id) NOT ENFORCED
) WITH (
  ''connector'' = ''mysql-cdc'',
  ''hostname''  = ''mysql57'',
  ''port''      = ''3306'',
  ''username''  = ''root'',
  ''password''  = ''sfdjfFF#s2332'',
  ''database-name'' = ''hydrology'',
  ''table-name''    = ''hyd_water_level'',
  ''server-time-zone'' = ''Asia/Shanghai'',
  ''scan.incremental.snapshot.enabled'' = ''true''
);
-- ========= 2) 目标表：Doris (ods.ods_hyd_water_level_flink_stream) via JDBC =========
-- 说明：用 JDBC 直接写 Doris FE(9030)，不需要 doris-connector，只需 mysql 驱动
CREATE TABLE sink_ods_hyd_water_level_flink_stream (
  id             BIGINT         COMMENT ''自增主键'',
  station_code   VARCHAR(64)    COMMENT ''站点编码（软关联）'',
  sensor_id      BIGINT         COMMENT ''传感器ID（软关联）'',
  obs_time       TIMESTAMP(3)   COMMENT ''观测时间'',
  obs_date       DATE           COMMENT ''观测日期'',
  water_level_m  DECIMAL(10,3)  COMMENT ''水位(米)'',
  quality_code   VARCHAR(16)    COMMENT ''质量代码'',
  source         VARCHAR(64)    COMMENT ''来源'',
  trace_id       VARCHAR(64)    COMMENT ''追踪ID/批次号'',
  ext_json       STRING         COMMENT ''扩展字段（原 JSON）'',
  created_at     TIMESTAMP(3)   COMMENT ''创建时间''
) WITH (
  ''connector'' = ''jdbc'',
  ''url'' = ''jdbc:mysql://host.docker.internal:9030/ods?useUnicode=true&characterEncoding=utf8&useSSL=false&rewriteBatchedStatements=true'',
  ''table-name'' = ''ods_hyd_water_level_flink_stream'',
  ''username'' = ''root'',
  ''password'' = ''InC3tmU4bijT4vkl'',
  ''driver''   = ''com.mysql.cj.jdbc.Driver'',
  -- flush 策略（按需调大吞吐）
  ''sink.buffer-flush.max-rows'' = ''5000'',
  ''sink.buffer-flush.interval'' = ''5s'',
  ''sink.max-retries'' = ''3''
);
-- ========= 3) 实时同步（JDBC 批量插入 Doris） =========
INSERT INTO sink_ods_hyd_water_level_flink_stream
SELECT
  id,
  CAST(station_code AS VARCHAR(64)) AS station_code,
  sensor_id,
  obs_time,
  obs_date,
  water_level_m,
  CAST(quality_code AS VARCHAR(16)) AS quality_code,
  CAST(source AS VARCHAR(64)) AS source,
  CAST(trace_id AS VARCHAR(64)) AS trace_id,
  ext_json,
  created_at
FROM src_hyd_water_level;
