CREATE TABLE hyd_water_level_sink (
    id             BIGINT,
    station_code   STRING,
    sensor_id      BIGINT,
    obs_time       TIMESTAMP(3),
    obs_date       DATE,
    water_level_m  DECIMAL(10,3),
    quality_code   STRING,
    source         STRING,
    trace_id       STRING,
    ext_json       STRING,
    created_at     TIMESTAMP(3),
    PRIMARY KEY (id) NOT ENFORCED
) WITH (
    ''connector'' = ''jdbc'',
    ''url''       = ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&serverTimezone=Asia/Shanghai'',
    ''table-name''= ''hyd_water_level_stream'',
    ''username''  = ''root'',
    ''password''  = ''sfdjfFF#s2332'',
    ''sink.buffer-flush.max-rows'' = ''500'',
    ''sink.buffer-flush.interval'' = ''2s'',
    ''sink.max-retries'' = ''3''
);
INSERT INTO hyd_water_level_sink
SELECT
    id,
    station_code,
    sensor_id,
    CAST(obs_time AS TIMESTAMP(3)) AS obs_time,
    obs_date,
    water_level_m,
    COALESCE(quality_code, ''OK'') AS quality_code,
    source,
    trace_id,
    ext_json,
    CAST(created_at AS TIMESTAMP(3)) AS created_at
FROM hyd_water_level_src;
