[INFO] 2025-09-22 15:58:31.720 - Writing content: -- ========= 1) 源表：MySQL (hydrology.hyd_water_level)  =========
CREATE TABLE src_hyd_water_level (
  id              BIGINT,              -- MySQL: bigint(20) unsigned AUTO_INCREMENT
  station_code    STRING,
  sensor_id       BIGINT,
  obs_time        TIMESTAMP(3),        -- MySQL: datetime
  obs_date        DATE,                -- MySQL: date
  water_level_m   DECIMAL(10,3),
  quality_code    STRING,
  source          STRING,
  trace_id        STRING,
  ext_json        STRING,              -- MySQL: text -> 以 STRING 读取
  created_at      TIMESTAMP(3),        -- MySQL: timestamp
  PRIMARY KEY (id) NOT ENFORCED
) WITH (
  ''connector'' = ''mysql-cdc'',
  ''hostname''  = ''mysql57'',
  ''port''      = ''3306'',
  ''username''  = ''root'',
  ''password''  = ''sfdjfFF#s2332'',
  ''database-name'' = ''hydrology'',
  ''table-name''    = ''hyd_water_level'',
  ''server-time-zone'' = ''Asia/Shanghai'',
  ''scan.incremental.snapshot.enabled'' = ''true''
);
-- ========= 2) 目标表：MySQL (hydrology.hyd_water_level_stream) =========
-- 字段类型与顺序与源表保持完全一致（id → created_at）
CREATE TABLE sink_hyd_water_level_stream (
  id              BIGINT,        -- 与源表一致
  station_code    STRING,
  sensor_id       BIGINT,
  obs_time        TIMESTAMP(3),
  obs_date        DATE,
  water_level_m   DECIMAL(10,3),
  quality_code    STRING,
  source          STRING,
  trace_id        STRING,
  ext_json        STRING,
  created_at      TIMESTAMP(3),
  PRIMARY KEY (id) NOT ENFORCED     -- 声明主键，JDBC Sink 才能处理更新/去重
) WITH (
  ''connector'' = ''jdbc'',
  ''url''       = ''jdbc:mysql://mysql57:3306/hydrology?useUnicode=true&characterEncoding=utf8&useSSL=false&rewriteBatchedStatements=true'',
  ''table-name'' = ''hyd_water_level_stream'',   -- 目标表名
  ''username''  = ''root'',
  ''password''  = ''sfdjfFF#s2332'',
  ''driver''    = ''com.mysql.cj.jdbc.Driver'',
  -- 批量写入/重试策略（可按需调整）
  ''sink.buffer-flush.max-rows'' = ''5000'',
  ''sink.buffer-flush.interval'' = ''5s'',
  ''sink.max-retries''           = ''3''
);
-- ========= 3) 实时同步（CDC -> MySQL JDBC） =========
INSERT INTO sink_hyd_water_level_stream
SELECT
  id,
  CAST(station_code AS STRING)  AS station_code,
  sensor_id,
  obs_time,
  obs_date,
  water_level_m,
  CAST(quality_code AS STRING)  AS quality_code,
  CAST(source       AS STRING)  AS source,
  CAST(trace_id     AS STRING)  AS trace_id,
  ext_json,
  created_at
FROM src_hyd_water_level;
