=====\r\n-- 字段类型与顺序与源表保持完全一致（id → created_at）\r\nCREATE TABLE sink_hyd_water_level_stream (\r\n  id              BIGINT,        -- 与源表一致\r\n  station_code    STRING,\r\n  sensor_id       BIGINT,\r\n  obs_time        TIMESTAMP(3),\r\n  obs_date        DATE,\r\n  water_level_m   DECIMAL(10,3),\r\n  quality_code    STRING,\r\n  source          STRING,\r\n  trace_id        STRING,\r\n  ext_json        STRING,\r\n  created_at      TIMESTAMP(3),\r\n  PRIMARY KEY (id) NOT ENFORCED     -- 声明主键，JDBC Sink 才能处理更新/去重\r\n) WITH (\r\n  ''connector'' = ''jdbc'',\r\n  ''url''       = ''jdbc:mysql://mysql57:3306/hydrology?useUnicode=true&characterEncoding=utf8&useSSL=false&rewriteBatchedStatements=true'',\r\n  ''table-name'' = ''hyd_water_level_stream'',   -- 目标表名\r\n  ''username''  = ''root'',\r\n  ''password''  = ''sfdjfFF#s2332'',\r\n  ''driver''    = ''com.mysql.cj.jdbc.Driver'',\r\n\r\n  -- 批量写入/重试策略（可按需调整）\r\n  ''sink.buffer-flush.max-rows'' = ''5000'',\r\n  ''sink.buffer-flush.interval'' = ''5s'',\r\n  ''sink.max-retries''           = ''3''\r\n);\r\n\r\n-- ========= 3) 实时同步（CDC -> MySQL JDBC） =========\r\nINSERT INTO sink_hyd_water_level_stream\r\nSELECT\r\n  id,\r\n  CAST(station_code AS STRING)  AS station_code,\r\n  sensor_id,\r\n  obs_time,\r\n  obs_date,\r\n  water_level_m,\r\n  CAST(quality_code AS STRING)  AS quality_code,\r\n  CAST(source       AS STRING)  AS source,\r\n  CAST(trace_id     AS STRING)  AS trace_id,\r\n  ext_json,\r\n  created_at\r\nFROM src_hyd_water_level;\r\n","executeMode":"STREAM"}','MEDIUM',0,1,0,0,-1,-1,'【MySQL → 达梦 ，实时同步】Flink 流处理导入历史水位数据  ',81,'1','0','吴同',2,TO_DATE('2025-09-22 15:58:03.309000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 15:58:03.309000','YYYY-MM-DD HH24:MI:SS.FF'),null,'55');
