E IF NOT EXISTS sink_hyd_water_level_stream (\r\n  id              BIGINT,\r\n  station_code    STRING,\r\n  sensor_id       BIGINT,\r\n  obs_time        TIMESTAMP(3),\r\n  obs_date        DATE,\r\n  water_level_m   DECIMAL(10,3),\r\n  quality_code    STRING,\r\n  source          STRING,\r\n  trace_id        STRING,\r\n  ext_json        STRING,\r\n  created_at      TIMESTAMP(3),\r\n  PRIMARY KEY (id) NOT ENFORCED\r\n) WITH (\r\n  ''connector'' = ''jdbc'',\r\n  ''url''       = ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&serverTimezone=Asia/Shanghai&useUnicode=true&characterEncoding=utf8'',\r\n  ''table-name'' = ''hyd_water_level_stream'',\r\n  ''username''  = ''root'',\r\n  ''password''  = ''sfdjfFF#s2332'',\r\n  ''driver''    = ''com.mysql.cj.jdbc.Driver'',\r\n  ''sink.buffer-flush.max-rows'' = ''5000'',\r\n  ''sink.buffer-flush.interval'' = ''5s'',\r\n  ''sink.max-retries''           = ''3''\r\n);\r\n\r\n-- ========= 3) 实时同步 =========\r\nINSERT INTO sink_hyd_water_level_stream\r\nSELECT\r\n  id,\r\n  station_code,\r\n  sensor_id,\r\n  obs_time,\r\n  obs_date,\r\n  water_level_m,\r\n  quality_code,\r\n  source,\r\n  trace_id,\r\n  ext_json,\r\n  created_at\r\nFROM src_hyd_water_level","executeMode":"STREAM"}','MEDIUM',0,1,0,0,-1,-1,'【实时同步，毫秒级延迟】Flink 流处理导入历史水位数据  ',81,'1','0','吴同',2,TO_DATE('2025-09-22 16:01:46.036000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 16:01:46.036000','YYYY-MM-DD HH24:MI:SS.FF'),null,'55');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(63,'3','FLINK','Flink流_水位信息采集','152659477902656',19,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":0,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"FlinkStream","datasourceId":"","sqlType":"0","taskType":"FLINK","segm":"","componentType":"55","localParams":[],"sql":"-- ========== 1) Source: MySQL CDC 读取 hydrology.hyd_water_level ==========\r\nCREATE TABLE hyd_water_level_src (\r\n  id             BIGINT,\r\n  station_code   STRING,\r\n  sensor_id      BIGINT,\r\n  obs_time       TIMESTAMP(3),\r\n  obs_date       DATE,\r\n  water_level_m  DECIMAL(10,3),\r\n  quality_code   STRING,\r\n  source         STRING,\r\n  trace_id       STRING,\r\n  ext_json       STRING,\r\n  created_at     TIMESTAMP(3),\r\n  PRIMARY KEY (id) NOT ENFORCED\r\n) WITH (\r\n  ''connector'' = ''mysql-cdc'',\r\n  ''hostname''  = ''mysql57'',\r\n  ''port''      = ''3306'',\r\n  ''username''  = ''root'',\r\n  ''password''  = ''sfdjfFF#s2332'',\r\n  ''database-name'' = ''hydrology'',\r\n  ''table-name''    = ''hyd_water_level'',\r\n\r\n  -- 初始全量 + 增量；若仅从最新 binlog 开始可设 ''scan.startup.mode''=''latest-offset''\r\n  ''scan.startup.mode'' = ''initial'',\r\n\r\n  -- 建议设置 server-id 范围，避免与其它 CDC 任务冲突\r\n  ''server-id'' = ''5400-5410'',\r\n\r\n  -- 可选：提高快照并发（根据库表规模与实例负载酌情）\r\n  ''scan.incremental.snapshot.enabled'' = ''true'',\r\n\r\n  -- 可选：Debezium 细节\r\n  ''debezium.snapshot.mode'' = ''initial'',\r\n  ''debezium.include.schema.changes'' = ''false''\r\n);\r\n\r\n-- ========== 2) Sink: MySQL JDBC 写入 hydrology.hyd_water_level_stream ==========\r\nCREATE TABLE hyd_water_level_sink (\r\n  id             BIGINT,\r\n  station_code   STRING,\r\n  sensor_id      BIGINT,\r\n  obs_time       TIMESTAMP(3),\r\n  obs_date       DATE,\r\n  water_level_m  DECIMAL(10,3),\r\n  quality_code   STRING,\r\n  source         STRING,\r\n  trace_id       STRING,\r\n  ext_json       STRING,\r\n  created_at     TIMESTAMP(3),\r\n  PRIMARY KEY (id) NOT ENFORCED\r\n) WITH (\r\n  ''connector'' = ''jdbc'',\r\n  ''url''       = ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  ''table-name''= ''hyd_water_level_stream'',\r\n  ''username''  = ''root'',\r\n  ''password''  = ''sfdjfFF#s2332'',\r\n\r\n  -- 开启删除下推（CDC 的 DELETE 会变成目标表 DELETE）\r\n  ''sink.delete.enabled'' = ''true'',\r\n\r\n  -- 写入缓冲（按需调整吞吐/延迟）\r\n  ''sink.buffer-flush.max-rows'' = ''500'',\r\n  ''sink.buffer-flush.interval'' = ''2s'',\r\n  ''sink.max-retries'' = ''3''\r\n);\r\n\r\n-- ========== 3) 实时同步：按主键 upsert（INSERT/UPDATE/DELETE） ==========\r\nINSERT INTO hyd_water_level_sink\r\nSELECT\r\n  id,\r\n  station_code,\r\n  sensor_id,\r\n  CAST(obs_time AS TIMESTAMP(3)) AS obs_time,\r\n  obs_date,\r\n  water_level_m,\r\n  COALESCE(quality_code, ''OK'') AS quality_code,\r\n  source,\r\n  trace_id,\r\n  ext_json,\r\n  CAST(created_at AS TIMESTAMP(3)) AS created_at\r\nFROM hyd_water_level_src;","executeMode":"STREAM"}','MEDIUM',0,1,0,0,-1,-1,'【实时同步，毫秒级延迟】Flink 流处理导入历史水位数据  ',81,'1','0','吴同',2,TO_DATE('2025-09-22 16:06:23.328000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 16:06:23.328000','YYYY-MM-DD HH24:MI:SS.FF'),null,'55');
