n    ''sink.max-retries'' = ''3''\r\n);\r\n\r\nINSERT INTO hyd_water_level_sink\r\nSELECT\r\n    id,\r\n    station_code\r\nFROM hyd_water_level_src;","executeMode":"STREAM"}','MEDIUM',0,1,0,0,-1,-1,'【实时同步，毫秒级延迟】Flink 流处理导入历史水位数据  ',81,'1','0','吴同',2,TO_DATE('2025-09-22 17:39:23.579000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 17:39:23.579000','YYYY-MM-DD HH24:MI:SS.FF'),null,'55');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(85,'3','SQL','Hive_水位日统计报表','152669873712448',1,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":1,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"DM","datasourceId":12,"sqlType":"0","taskType":"SQL","segm":"","componentType":"51","localParams":[],"executeMode":"","datasources":{"datasourceType":"DM8","datasourceConfig":"{\"username\":\"WATER_TP\",\"password\":\"lmOxx+3wDu3oUMxRKAR3LQ==\",\"dbname\":\"WATER_TP\"}","ip":"dm8-demo","port":5236,"dbname":"WATER_TP","datasource_id":12,"datasourceId":12},"sql":"-- 源：MySQL 水位明细（只读外部表）\r\nCREATE EXTERNAL TABLE IF NOT EXISTS hyd_water_level_mysql (\r\n  id             BIGINT,\r\n  station_code   STRING,\r\n  sensor_id      BIGINT,\r\n  obs_time       TIMESTAMP,\r\n  obs_date       DATE,\r\n  water_level_m  DECIMAL(10,3),\r\n  quality_code   STRING,\r\n  source         STRING,\r\n  trace_id       STRING,\r\n  ext_json       STRING,\r\n  created_at     TIMESTAMP\r\n)\r\nSTORED BY ''org.apache.hive.storage.jdbc.JdbcStorageHandler''\r\nTBLPROPERTIES (\r\n  ''hive.sql.database.type'' = ''MYSQL'',\r\n  ''hive.sql.jdbc.driver''   = ''com.mysql.cj.jdbc.Driver'',\r\n  ''hive.sql.jdbc.url''      = ''jdbc:mysql://mysql57:3306/hydrology?useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  ''hive.sql.dbcp.username'' = ''root'',\r\n  ''hive.sql.dbcp.password'' = ''sfdjfFF#s2332'',\r\n  ''hive.sql.table''         = ''hyd_water_level''\r\n);\r\n\r\n-- 可选维表：如没有也可以建（空表不会影响 LEFT JOIN 结果）\r\nCREATE EXTERNAL TABLE IF NOT EXISTS hyd_station_mysql (\r\n  station_id   BIGINT,\r\n  station_code STRING,\r\n  station_name STRING\r\n)\r\nSTORED BY ''org.apache.hive.storage.jdbc.JdbcStorageHandler''\r\nTBLPROPERTIES (\r\n  ''hive.sql.database.type'' = ''MYSQL'',\r\n  ''hive.sql.jdbc.driver''   = ''com.mysql.cj.jdbc.Driver'',\r\n  ''hive.sql.jdbc.url''      = ''jdbc:mysql://mysql57:3306/hydrology?useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  ''hive.sql.dbcp.username'' = ''root'',\r\n  ''hive.sql.dbcp.password'' = ''sfdjfFF#s2332'',\r\n  ''hive.sql.table''         = ''hyd_station''\r\n);\r\n\r\n-- 中间结果表（列顺序/类型与 Doris 目标表一致）\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_stage (\r\n  station_id      BIGINT,\r\n  station_name    STRING,\r\n  avg_level_year  DECIMAL(10,3),  -- 实际写入：日平均水位\r\n  stat_date       DATE\r\n)\r\nSTORED AS PARQUET;\r\n\r\n-- 计算“日平均水位”并落中间表\r\nWITH base AS (\r\n  SELECT\r\n    station_code,\r\n    COALESCE(obs_date, CAST(obs_time AS DATE))   AS stat_date,\r\n    CAST(water_level_m AS DOUBLE)                AS water_level_m\r\n  FROM hyd_water_level_mysql\r\n  WHERE water_level_m IS NOT NULL\r\n),\r\nday_avg AS (\r\n  SELECT\r\n    station_code,\r\n    stat_date,\r\n    AVG(water_level_m) AS avg_level_day\r\n  FROM base\r\n  GROUP BY station_code, stat_date\r\n)\r\nINSERT OVERWRITE TABLE dws_station_water_day_report_stage\r\nSELECT\r\n  COALESCE(s.station_id, CAST(NULL AS BIGINT))              AS station_id,\r\n  COALESCE(s.station_name, CAST(d.station_code AS STRING))  AS station_name,\r\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))          AS avg_level_year,\r\n  d.stat_date                                               AS stat_date\r\nFROM day_avg d\r\nLEFT JOIN hyd_station_mysql s\r\n  ON s.station_code = d.station_code;\r\n"}','MEDIUM',0,1,0,1,-1,-1,'【离线计算】 查询水位实时数据，生成每日统计报表    （Hive 非完全版，无法运行）',87,'1','0','吴同',2,TO_DATE('2025-09-22 17:45:46.606000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 17:45:46.606000','YYYY-MM-DD HH24:MI:SS.FF'),null,'51');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(87,'3','SQL','Hive_水位日统计报表','152672440882496',1,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":0,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"Hive","datasourceId":8,"sqlType":"0","taskType":"SQL","segm":"","componentType":"51","localParams":[],"executeMode":"","datasources":{"datasourceType":"Hive","datasourceConfig":"{\"username\":\"admin\",\"password\":\"EUnSflaQclN6qLxLG6pUbg==\",\"dbname\":\"default\"}","ip":"hive","port":10000,"dbname":"default","datasource_id":8,"datasourceId":8},"sql":"-- ========== 1) 源：MySQL 水位明细 ==========\r\nCREATE TEMPORARY VIEW hyd_water_level_src\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\r\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\r\nCREATE TEMPORARY VIEW hyd_station_dim\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_station'',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''dws_station_water_day_report'',\r\n  user ''root'',\r\n  password ''InC3tmU4bijT4vkl'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\r\nWITH base AS (\r\n  SELECT\r\n    wl.station_code,\r\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\r\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\r\n  FROM hyd_water_level_src wl\r\n  WHERE wl.water_level_m IS NOT NULL\r\n),\r\nday_avg AS (\r\n  SELECT\r\n    station_code,\r\n    stat_date,\r\n    AVG(water_level_m) AS avg_level_day\r\n  FROM base\r\n  GROUP BY station_code, stat_date\r\n)\r\n\r\nINSERT INTO dws_station_water_day_report_jdbc\r\nSELECT\r\n  -- station_id：有维表用维表，没有则置 NULL\r\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\r\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\r\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\r\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\r\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\r\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\r\nFROM day_avg d\r\nLEFT JOIN hyd_station_dim s\r\n  ON s.station_code = d.station_code;"}','MEDIUM',0,1,0,0,-1,-1,'【离线计算】 查询水位实时数据，生成每日统计报表    （Hive 非完全部署，任务无法运行）',89,'1','0','吴同',2,TO_DATE('2025-09-22 18:03:55.943000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 18:03:55.943000','YYYY-MM-DD HH24:MI:SS.FF'),null,'51');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(88,'3','SQL','Hive_水位日统计报表','152672440882496',2,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":0,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"Hive","datasourceId":8,"sqlType":"0","taskType":"SQL","segm":"","componentType":"51","localParams":[],"executeMode":"","datasources":{"datasourceType":"Hive","datasourceConfig":"{\"username\":\"admin\",\"password\":\"EUnSflaQclN6qLxLG6pUbg==\",\"dbname\":\"default\"}","ip":"hive","port":10000,"dbname":"default","datasource_id":8,"datasourceId":8},"sql":"-- ========== 1) 源：MySQL 水位明细 ==========\r\nCREATE TEMPORARY VIEW hyd_water_level_src\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 2) 可选维度：站点表（如没有可保留，后续会自动降级为用 station_code 代替名称）==========\r\n-- 期望列：station_id BIGINT, station_code VARCHAR, station_name VARCHAR\r\nCREATE TEMPORARY VIEW hyd_station_dim\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_station'',                       -- 没有就保持这样；后续 LEFT JOIN + COALESCE 兼容\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 3) 目标：Doris 报表（通过 MySQL 协议）==========\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://host.docker.internal:9030/dws?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''dws_station_water_day_report'',\r\n  user ''root'',\r\n  password ''InC3tmU4bijT4vkl'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- ========== 4) 计算“日平均水位”并写入目标 ==========\r\nWITH base AS (\r\n  SELECT\r\n    wl.station_code,\r\n    COALESCE(wl.obs_date, CAST(wl.obs_time AS DATE)) AS stat_date,\r\n    CAST(wl.water_level_m AS DOUBLE)                  AS water_level_m\r\n  FROM hyd_water_level_src wl\r\n  WHERE wl.water_level_m IS NOT NULL\r\n),\r\nday_avg AS (\r\n  SELECT\r\n    station_code,\r\n    stat_date,\r\n    AVG(water_level_m) AS avg_level_day\r\n  FROM base\r\n  GROUP BY station_code, stat_date\r\n)\r\n\r\nINSERT INTO dws_station_water_day_report_jdbc\r\nSELECT\r\n  -- station_id：有维表用维表，没有则置 NULL\r\n  COALESCE(CAST(s.station_id AS BIGINT), CAST(NULL AS BIGINT))             AS station_id,\r\n  -- station_name：有维表用维表名称，没有则用 station_code 顶上\r\n  COALESCE(CAST(s.station_name AS STRING), CAST(d.station_code AS STRING)) AS station_name,\r\n  -- 写入日平均（保留三位小数），沿用目标表列名 avg_level_year\r\n  CAST(ROUND(d.avg_level_day, 3) AS DECIMAL(10,3))                          AS avg_level_year,\r\n  CAST(d.stat_date AS DATE)                                                 AS stat_date\r\nFROM day_avg d\r\nLEFT JOIN hyd_station_dim s\r\n  ON s.station_code = d.station_code;"}','MEDIUM',0,1,0,0,-1,-1,'【离线计算】 查询水位实时数据，生成每日统计报表    （Hive 非完全部署，任务无法运行）',89,'1','0','吴同',2,TO_DATE('2025-09-22 18:06:41.882000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 18:06:41.882000','YYYY-MM-DD HH24:MI:SS.FF'),null,'51');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(89,'3','SQL','达梦_水位日统计','152671899571520',1,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":1,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"DM","datasourceId":12,"sqlType":"2","taskType":"SQL","segm":"","componentType":"51","localParams":[],"executeMode":"","datasources":{"datasourceType":"DM8","datasourceConfig":"{\"username\":\"WATER_TP\",\"password\":\"lmOxx+3wDu3oUMxRKAR3LQ==\",\"dbname\":\"WATER_TP\"}","ip":"dm8-demo","port":5236,"dbname":"WATER_TP","datasource_id":12,"datasourceId":12},"sql":"-- 在这里输入内容2323"}','MEDIUM',0,1,0,1,-1,-1,'【存储过程】查询水位实时数据，生成每日统计报表  ',90,'1','0','吴同',2,TO_DATE('2025-09-22 18:07:03.322000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 18:07:03.322000','YYYY-MM-DD HH24:MI:SS.FF'),null,'51');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(90,'3','PROCEDURE','达梦_水位日统计','152671899571520',2,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":1,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"DM","datasourceId":12,"sqlType":"2","taskType":"PROCEDURE","segm":"","componentType":"52","localParams":[],"sql":"/* =========================\r\n   0) 可选：站点维表（如已有可跳过）\r\n   ========================= */\r\n-- CREATE TABLE HYD_STATION(\r\n--   STATION_ID    NUMBER(20),\r\n--   STATION_CODE  VARCHAR2(64),\r\n--   STATION_NAME  VARCHAR2(128),\r\n--   CONSTRAINT PK_HYD_STATION PRIMARY KEY(STATION_ID)\r\n--);\r\n\r\n/* =========================\r\n   1) 日报表表（DM 建表；若已存在可跳过）\r\n   ========================= */\r\nCREATE TABLE IF NOT EXISTS DWS_STATION_WATER_DAY_REPORT (\r\n  STATION_ID     NUMBER(20),          -- 测站ID（允许为NULL：当没维表时）\r\n  STATION_NAME   VARCHAR2(128),       -- 测站名称（无维表时用 STATION_CODE 顶上）\r\n  AVG_LEVEL_DAY  NUMBER(10,3),        -- 日平均水位(米)\r\n  STAT_DATE      DATE,                -- 统计日期（按天）\r\n  CONSTRAINT UK_DWS_WATER_DAY UNIQUE (STATION_ID, STAT_DATE)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS IDX_DWS_WATER_DAY_D ON DWS_STATION_WATER_DAY_REPORT(STAT_DATE);\r\n\r\n/* =========================\r\n   2) 单日生成存储过程\r\n   说明：\r\n   - 参数 p_stat_date：统计哪一天；默认取 SYSDATE 的日期部分。\r\n   - 逻辑：按站点、当天聚合 AVG(water_level_m) -> MERGE 到报表（upsert）\r\n   ========================= */\r\nCREATE OR REPLACE PROCEDURE PRC_GEN_WATER_DAY_REPORT(\r\n  p_stat_date IN DATE DEFAULT TRUNC(SYSDATE)\r\n) AS\r\nBEGIN\r\n  MERGE INTO DWS_STATION_WATER_DAY_REPORT T\r\n  USING (\r\n    SELECT\r\n      S.STATION_ID,\r\n      /* 无维表名称时，用 STATION_CODE 作为名称兜底 */\r\n      COALESCE(S.STATION_NAME, WL.STATION_CODE) AS STATION_NAME,\r\n      ROUND(AVG(CAST(WL.WATER_LEVEL_M AS NUMBER(10,3))), 3) AS AVG_LEVEL_DAY,\r\n      p_stat_date AS STAT_DATE\r\n    FROM HYD_WATER_LEVEL WL\r\n    LEFT JOIN HYD_STATION S\r\n      ON S.STATION_CODE = WL.STATION_CODE\r\n    WHERE (CASE\r\n             WHEN WL.OBS_DATE IS NOT NULL THEN WL.OBS_DATE\r\n             ELSE TRUNC(WL.OBS_TIME)\r\n           END) = p_stat_date\r\n      AND WL.WATER_LEVEL_M IS NOT NULL\r\n    GROUP BY S.STATION_ID, COALESCE(S.STATION_NAME, WL.STATION_CODE)\r\n  ) X\r\n  ON (T.STATION_ID = X.STATION_ID AND T.STAT_DATE = X.STAT_DATE)\r\n  WHEN MATCHED THEN\r\n    UPDATE SET\r\n      T.STATION_NAME  = X.STATION_NAME,\r\n      T.AVG_LEVEL_DAY = X.AVG_LEVEL_DAY\r\n  WHEN NOT MATCHED THEN\r\n    INSERT (T.STATION_ID, T.STATION_NAME, T.AVG_LEVEL_DAY, T.STAT_DATE)\r\n    VALUES (X.STATION_ID, X.STATION_NAME, X.AVG_LEVEL_DAY, X.STAT_DATE);\r\n\r\n  COMMIT;\r\nEND;\r\n/\r\n\r\n/* =========================\r\n   3) 区间生成存储过程（含游标循环）\r\n   说明：\r\n   - 按起止日期逐日调用单日过程，适合补历史。\r\n   ========================= */\r\nCREATE OR REPLACE PROCEDURE PRC_GEN_WATER_DAY_REPORT_RANGE(\r\n  p_begin_date IN DATE,   -- 起始（含）\r\n  p_end_date   IN DATE    -- 截止（含）\r\n) AS\r\n  v_day DATE;\r\nBEGIN\r\n  IF p_begin_date IS NULL OR p_end_date IS NULL THEN\r\n    RAISE_APPLICATION_ERROR(-20001, ''起止日期不可为空'');\r\n  END IF;\r\n\r\n  IF TRUNC(p_begin_date) > TRUNC(p_end_date) THEN\r\n    RAISE_APPLICATION_ERROR(-20002, ''起始日期不能晚于截止日期'');\r\n  END IF;\r\n\r\n  v_day := TRUNC(p_begin_date);\r\n  WHILE v_day <= TRUNC(p_end_date) LOOP\r\n    PRC_GEN_WATER_DAY_REPORT(v_day);\r\n    v_day := v_day + 1;\r\n  END LOOP;\r\n\r\n  COMMIT;\r\nEND;\r\n/\r\n\r\n/* =========================\r\n   4) 调用示例\r\n   ========================= */\r\n-- 生成“今天”的报表（按服务器当前日期）\r\nCALL PRC_GEN_WATER_DAY_REPORT();\r\n\r\n-- 生成指定日期\r\nCALL PRC_GEN_WATER_DAY_REPORT(TO_DATE(''2025-01-01'', ''YYYY-MM-DD''));\r\n\r\n-- 生成一段时间（含首尾），例如 2025-01-01 ~ 2025-01-07\r\nCALL PRC_GEN_WATER_DAY_REPORT_RANGE(\r\n  TO_DATE(''2025-01-01'', ''YYYY-MM-DD''),\r\n  TO_DATE(''2025-01-07'', ''YYYY-MM-DD'')\r\n);\r\n\r\n/* =========================\r\n   5) 查询校验\r\n   ========================= */\r\n-- 看最新 10 条\r\nSELECT *\r\nFROM DWS_STATION_WATER_DAY_REPORT\r\nORDER BY STAT_DATE DESC, STATION_ID\r\nFETCH FIRST 10 ROWS ONLY;","executeMode":"","datasources":{"datasourceType":"DM8","datasourceConfig":"{\"username\":\"WATER_TP\",\"password\":\"lmOxx+3wDu3oUMxRKAR3LQ==\",\"dbname\":\"WATER_TP\"}","ip":"dm8-demo","port":5236,"dbname":"WATER_TP","datasource_id":12,"datasourceId":12}}','MEDIUM',0,1,0,1,-1,-1,'【存储过程】查询水位实时数据，生成每日统计报表  ',90,'1','0','吴同',2,TO_DATE('2025-09-22 18:07:40.110000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 18:07:40.110000','YYYY-MM-DD HH24:MI:SS.FF'),null,'52');
INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(91,'3','SQL','MySQL_水位日统计','152672766952768',1,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":0,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"MYSQL","datasourceId":11,"sqlType":"0","taskType":"SQL","segm":"","componentType":"51","localParams":[],"executeMode":"","datasources":{"datasourceType":"MySql","datasourceConfig":"{\"username\":\"root\",\"password\":\"NEdUNkrJO8YbZBIi9M2nOg==\",\"dbname\":\"hydrology\"}","ip":"mysql57","port":3306,"dbname":"hydrology","datasource_id":11,"datasourceId":11},"sql":"/* ===========================================================\r\n   环境准备（按需修改库名）\r\n   =========================================================== */\r\n-- 可选：使用你的业务库\r\nCREATE DATABASE IF NOT EXISTS hydrology DEFAULT CHARACTER SET utf8mb4;\r\nUSE hydrology;\r\n\r\n/* ===========================================================\r\n   1) 报表表（日平均水位）\r\n   - 以 (station_code, stat_date) 做唯一键，兼容无维表场景\r\n   - 如存在维表，会同步写入 station_id / station_name\r\n   =========================================================== */\r\nCREATE TABLE IF NOT EXISTS dws_station_water_day_report (\r\n  station_code   VARCHAR(64)  NOT NULL COMMENT ''测站编码'',\r\n  station_id     BIGINT                COMMENT ''测站ID（有维表时填充）'',\r\n  station_name   VARCHAR(128)          COMMENT ''测站名称（有维表时填充；无维表时=station_code）'',\r\n  avg_level_day  DECIMAL(10,3)         COMMENT ''日平均水位(米)'',\r\n  stat_date      DATE         NOT NULL COMMENT ''统计日期'',\r\n  PRIMARY KEY (station_code, stat_date),\r\n  KEY idx_stat_date (stat_date),\r\n  KEY idx_station_id (station_id)\r\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=''站点水位日统计（日均）'';\r\n\r\n/* ===========================================================\r\n   2) 单日报表过程\r\n   - 输入：p_stat_date（统计yyyy-MM-dd）\r\n   - 逻辑：\r\n       取 obs_date，否则取 DATE(obs_time) 作为统计日期\r\n       按 (station_code, stat_date) 聚合 AVG(water_level_m)\r\n       LEFT JOIN hyd_station（如存在）填充 id/name\r\n       用 ON DUPLICATE KEY 做 upsert\r\n   =========================================================== */\r\nDELIMITER $$\r\n\r\nDROP PROCEDURE IF EXISTS prc_gen_water_day_report $$\r\nCREATE PROCEDURE prc_gen_water_day_report(IN p_stat_date DATE)\r\nBEGIN\r\n  /*\r\n    说明：\r\n    - 若不存在 hyd_station 表，LEFT JOIN 返回 NULL，不影响执行；\r\n      station_id 将为 NULL，station_name 用 station_code 兜底。\r\n    - hyd_water_level 建议在 hydrology 库中（按需改库名前缀）。\r\n  */\r\n  INSERT INTO dws_station_water_day_report\r\n  (\r\n    station_code, station_id, station_name, avg_level_day, stat_date\r\n  )\r\n  SELECT\r\n    wl.station_code                                                AS station_code,\r\n    s.station_id                                                   AS station_id,               -- 可能为 NULL\r\n    COALESCE(s.station_name, wl.station_code)                      AS station_name,             -- 兜底\r\n    ROUND(AVG(CAST(wl.water_level_m AS DECIMAL(10,3))), 3)         AS avg_level_day,\r\n    p_stat_date                                                    AS stat_date\r\n  FROM hydrology.hyd_water_level wl\r\n  LEFT JOIN hydrology.hyd_station s\r\n    ON s.station_code = wl.station_code\r\n  WHERE\r\n      (CASE\r\n         WHEN wl.obs_date IS NOT NULL THEN wl.obs_date\r\n         ELSE DATE(wl.obs_time)\r\n       END) = p_stat_date\r\n    AND wl.water_level_m IS NOT NULL\r\n  GROUP BY wl.station_code, s.station_id, COALESCE(s.station_name, wl.station_code)\r\n  ON DUPLICATE KEY UPDATE\r\n      station_id     = VALUES(station_id),\r\n      station_name   = VALUES(station_name),\r\n      avg_level_day  = VALUES(avg_level_day);\r\nEND $$\r\nDELIMITER ;\r\n\r\n/* ===========================================================\r\n   3) 区间报表过程（含首尾）\r\n   =========================================================== */\r\nDELIMITER $$\r\n\r\nDROP PROCEDURE IF EXISTS prc_gen_water_day_report_range $$\r\nCREATE PROCEDURE prc_gen_water_day_report_range(IN p_begin_date DATE, IN p_end_date DATE)\r\nBEGIN\r\n  DECLARE v_day DATE;\r\n\r\n  IF p_begin_date IS NULL OR p_end_date IS NULL THEN\r\n    SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''起止日期不可为空'';\r\n  END IF;\r\n\r\n  IF p_begin_date > p_end_date THEN\r\n    SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''起始日期不能晚于截止日期'';\r\n  END IF;\r\n\r\n  SET v_day = p_begin_date;\r\n  WHILE v_day <= p_end_date DO\r\n    CALL prc_gen_water_day_report(v_day);\r\n    SET v_day = DATE_ADD(v_day, INTERVAL 1 DAY);\r\n  END WHILE;\r\nEND $$\r\nDELIMITER ;\r\n\r\n/* ===========================================================\r\n   4) 使用示例\r\n   =========================================================== */\r\n-- 生成某一天（例如 2025-01-01）\r\nCALL prc_gen_water_day_report(''2025-01-01'');\r\n\r\n-- 生成一段时间（例如 2025-01-01 ~ 2025-01-07）\r\nCALL prc_gen_water_day_report_range(''2025-01-01'', ''2025-01-07'');\r\n\r\n-- 校验\r\nSELECT *\r\nFROM dws_station_water_day_report\r\nORDER BY stat_date DESC, station_code\r\nLIMIT 20;\r\n\r\n/* ===========================================================\r\n   5) （可选）事件调度：每天 00:10 生成“昨日日报”\r\n   - 需要：SET GLOBAL event_scheduler = ON;\r\n   - 如不需要可删除此段\r\n   =========================================================== */\r\nSET GLOBAL event_scheduler = ON;\r\n\r\nCREATE EVENT IF NOT EXISTS evt_gen_water_day_report_yesterday\r\nON SCHEDULE EVERY 1 DAY\r\nSTARTS TIMESTAMP(CURRENT_DATE, ''00:10:00'')\r\nDO\r\n  CALL prc_gen_water_day_report(DATE_SUB(CURDATE(), INTERVAL 1 DAY));\r\n"}','MEDIUM',0,1,0,0,-1,-1,'【MySQL  存储过程】查询水位实时数据，生成每日统计报表  ',91,'1','0','吴同',2,TO_DATE('2025-09-22 18:13:05.667000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-22 18:13:05.667000','YYYY-MM-DD HH24:MI:SS.FF'),null,'51');
