INSERT INTO "QDATA"."DPP_ETL_NODE_LOG"("ID","TASK_TYPE","TYPE","NAME","CODE","VERSION","PROJECT_ID","PROJECT_CODE","PARAMETERS","PRIORITY","FAIL_RETRY_TIMES","FAIL_RETRY_INTERVAL","TIMEOUT","DELAY_TIME","CPU_QUOTA","MEMORY_MAX","DESCRIPTION","DS_ID","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","COMPONENT_TYPE") VALUES(123,'3','SPARK','SparkSQL_水位日统计报表','152726374059328',1,1,'152317790975712','{"taskPriority":"MEDIUM","workerGroup":"default","failRetryTimes":0,"failRetryInterval":1,"delayTime":0,"jobManagerMemory":"1G","taskManagerMemory":"2G","slot":1,"taskManager":2,"parallelism":1,"yarnQueue":"","driverCores":1,"driverMemory":"512M","numExecutors":1,"executorMemory":"1G","executorCores":1,"typaCode":"SparkSql","datasourceId":"","sqlType":"0","taskType":"SPARK","segm":"","componentType":"53","localParams":[],"executeMode":"","sql":"-- 建议：控制并行度（按你的集群修改）\r\nSET spark.sql.shuffle.partitions=4;\r\n\r\n-- 1) 源表（MySQL）注册为临时视图\r\nCREATE TEMPORARY VIEW hyd_water_level_src\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- 2) 目标表（MySQL）作为可写的数据源表（映射到已存在的 hyd_water_level_spark）\r\n--    注意：这里不会在 MySQL 里建表，只是把这个 JDBC 映射成 Spark SQL 的一张可写表\r\nCREATE TABLE IF NOT EXISTS hyd_water_level_spark_jdbc\r\nUSING jdbc\r\nOPTIONS (\r\n  url ''jdbc:mysql://mysql57:3306/hydrology?useSSL=false&useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai'',\r\n  dbtable ''hyd_water_level_spark'',\r\n  user ''root'',\r\n  password ''sfdjfFF#s2332'',\r\n  driver ''com.mysql.cj.jdbc.Driver''\r\n);\r\n\r\n-- 3) 全量复制（保留 id）\r\nINSERT INTO hyd_water_level_spark_jdbc\r\nSELECT\r\n  id,\r\n  station_code,\r\n  sensor_id,\r\n  obs_time,\r\n  obs_date,\r\n  water_level_m,\r\n  quality_code,\r\n  source,\r\n  trace_id,\r\n  ext_json,\r\n  created_at\r\nFROM hyd_water_level_src;"}','MEDIUM',0,1,0,0,-1,-1,'【离线计算】查询水位实时数据，生成每日统计报表',100,'1','0','吴同',2,TO_DATE('2025-09-23 09:03:18.590000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-23 09:03:18.590000','YYYY-MM-DD HH24:MI:SS.FF'),null,'53');
