WITH (
    ''connector'' = ''kafka''
)
AS SELECT id, name, age FROM source_table WHERE mod(id, 10) = 0;','CREATE TABLE ctas_kafka','1','0',null,null,TO_DATE('2025-06-25 14:20:54.401989','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-06-25 14:20:54.401994','YYYY-MM-DD HH24:MI:SS.FF'),null);
