${4:}','note template','1','0',null,null,TO_DATE('2025-06-25 14:20:55.608252','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-06-25 14:20:55.608259','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."DPP_ETL_SQL_TEMP"("ID","NAME","TYPE","CONTENT","DESCRIPTION","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(18,'dinky_paimon_auto_create_table','10','-- -----------------------------------------------------------------
-- 该 demo 用于创建 mysql-cdc 到 paimon 的整库同步案例 并使用自动建表,注意 #{schemaName} 和 #{tableName} 为固定写法,不要修改,用于动态获取库名和表名
-- -----------------------------------------------------------------
EXECUTE CDCSOURCE dinky_paimon_auto_create_table
WITH
  (
    ''connector'' = ''mysql-cdc'',
    ''hostname'' = '''',
    ''port'' = '''',
    ''username'' = '''',
    ''password'' = '''',
    ''checkpoint'' = ''10000'',
    ''parallelism'' = ''1'',
    ''scan.startup.mode'' = ''initial'',
    ''database-name'' = ''dinky'',
    ''sink.connector'' = ''paimon'',
    ''sink.path'' = ''hdfs:/tmp/paimon/#{schemaName}.db/#{tableName}'',
    ''sink.auto-create'' = ''true'',
  );','dinky_paimon_auto_create_table','1','0',null,null,TO_DATE('2025-06-25 14:20:55.840366','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-06-25 14:20:55.840370','YYYY-MM-DD HH24:MI:SS.FF'),null);
