INSERT INTO "QDATA"."DPP_EVALUATE_LOG"("ID","TABLE_NAME","COLUMN_NAME","RULE_CODE","RULE_NAME","DIMENSION_TYPE","RULE_DESCRIPTION","TASK_LOG_ID","EVALUATE_ID","TOTAL","PROBLEM_TOTAL","CHECK_DATE","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","RULE") VALUES(22,'STATION','STATION_CODE','107','字段字符类型校验','2','【准确性：字段字符类型校验】检查station_code不为空，且必须符合统一格式（如^[A-Z0-9_-]{3,32}$），避免站点编码缺失或异常。','1','1',504,0,TO_DATE('2025-09-23 11:37:07.235000','YYYY-MM-DD HH24:MI:SS.FF'),'1','0',null,null,TO_DATE('2025-09-23 11:37:07.242000','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-09-23 11:37:07.242000','YYYY-MM-DD HH24:MI:SS.FF'),null,'{"ignoreNullValue":"1","regex":"^[A-Z0-9_-]{3,32}$","errDescription":"","evaColumns":[{"name":"STATION_ID","label":"STATION_ID/站点主键（源）"},{"name":"STATION_CODE","label":"STATION_CODE/站点编码（跨源统一关联键）"},{"name":"STATION_NAME","label":"STATION_NAME/站点名称"},{"name":"BASIN_CODE","label":"BASIN_CODE/流域编码"},{"name":"RIVER_NAME","label":"RIVER_NAME/河流名称"},{"name":"LONGITUDE","label":"LONGITUDE/经度"},{"name":"LATITUDE","label":"LATITUDE/纬度"},{"name":"ADMIN_REGION_CODE","label":"ADMIN_REGION_CODE/行政区划码"},{"name":"STATUS","label":"STATUS/1启用/0停用"},{"name":"CREATED_AT","label":"CREATED_AT/创建时间"},{"name":"UPDATED_AT","label":"UPDATED_AT/修改时间"}],"suggestion":"","warningLevel":"2","evaluateName":"站点编码非空与格式稽查","useRegexFlag":1,"allowedChars":["1"]}');
