INSERT INTO "QDATA"."DPP_EVALUATE_LOG"("ID","TABLE_NAME","COLUMN_NAME","RULE_CODE","RULE_NAME","DIMENSION_TYPE","RULE_DESCRIPTION","TASK_LOG_ID","EVALUATE_ID","TOTAL","PROBLEM_TOTAL","CHECK_DATE","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK","RULE") VALUES(24,'ods_wr_station','longitude','306','数值字段范围校验','3','【一致性：数值字段范围校验】校验经纬度是否落在合理区间（经度 -180180，纬度 -9090），小数位不得超过 6 位。','4','7',16000,7980,TO_DATE('2025-09-23 11:37:13.303000','YYYY-MM-DD HH24:MI:SS.FF'),'1','0',null,null,TO_DATE('2025-09-23 11:37:13.407000','YYYY-MM-DD HH24:MI:SS.FF'),null,null,TO_DATE('2025-09-23 11:37:13.407000','YYYY-MM-DD HH24:MI:SS.FF'),null,'{"includeBoundary":"1","minValue":"-180180","errDescription":"","maxValue":"115","evaColumns":[{"name":"station_id","label":"station_id/站点主键（源）"},{"name":"station_code","label":"station_code/站点编码（跨源统一关联键）"},{"name":"station_name","label":"station_name/站点名称"},{"name":"basin_code","label":"basin_code/流域编码"},{"name":"river_name","label":"river_name/河流名称"},{"name":"longitude","label":"longitude/经度"},{"name":"latitude","label":"latitude/纬度"},{"name":"admin_region_code","label":"admin_region_code/行政区划码"},{"name":"status","label":"status/1启用/0停用"},{"name":"created_at","label":"created_at/创建时间"},{"name":"updated_at","label":"updated_at/修改时间"}],"suggestion":"","warningLevel":"2","evaluateName":"站点经纬度范围与精度稽查"}');

