COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."create_by" IS '创建人';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."create_time" IS '创建时间';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."update_by" IS '修改人';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."update_time" IS '修改时间';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."del_flag" IS '删除标识0-正常,1-已删除';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."api_method" IS '请求方法0-get,1-post';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."api_code" IS '请求编码';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."template" IS '是否是模板 0-是,1-不是';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."view_count" IS '浏览次数';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."css_str" IS 'css增强';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."js_str" IS 'js增强';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."py_str" IS 'py增强';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."tenant_id" IS '多租户标识';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."update_count" IS '乐观锁版本';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT"."submit_form" IS '是否填报报表 0不是,1是';

COMMENT ON TABLE "QDATA"."JIMU_REPORT_SHARE" IS '积木报表预览权限表';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."id" IS '主键';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."report_id" IS '在线excel设计器id';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."preview_url" IS '预览地址';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."preview_lock" IS '密码锁';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."last_update_time" IS '最后更新时间';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."term_of_validity" IS '有效期(0:永久有效，1:1天，2:7天)';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."status" IS '是否过期(0未过期，1已过期)';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."preview_lock_status" IS '密码锁状态(0不存在密码锁，1存在密码锁)';

COMMENT ON COLUMN "QDATA"."JIMU_REPORT_SHARE"."share_token" IS '分享token';

