INSERT INTO "QDATA"."ATT_CLIENT"("ID","NAME","TYPE","SECRET","HOMEPAGE_URL","ALLOW_URL","SYNC_URL","LOGO","DESCRIPTION","PUBLIC_FLAG","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(3,'政务服务网','0','abbaa60f2f4b491f82269ebc3c083b35',null,null,null,null,'作为上级业务平台，数据中台向该系统推送用水计划审批结果、申报状态更新等数据，实现审批信息回流与状态同步。','1','1','0','吴同',2,TO_DATE('2025-09-18 15:26:57.948000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-18 15:26:57.948000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."ATT_CLIENT"("ID","NAME","TYPE","SECRET","HOMEPAGE_URL","ALLOW_URL","SYNC_URL","LOGO","DESCRIPTION","PUBLIC_FLAG","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(4,'水文测报系统','0','acfccbfc8d8e406f9e74925bb51c08c1',null,null,null,null,'作为同级平台，需从中台同步基础水文监测数据，经中台统一接入、清洗、治理后提供标准化服务。','1','1','0','吴同',2,TO_DATE('2025-09-18 15:27:13.838000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-18 15:27:13.838000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."ATT_CLIENT"("ID","NAME","TYPE","SECRET","HOMEPAGE_URL","ALLOW_URL","SYNC_URL","LOGO","DESCRIPTION","PUBLIC_FLAG","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(5,'灌区信息化系统','0','53ef84d0d89a4a6c8c03412c2f769438',null,null,null,'/profile/2025/09/18/68cbb45de4b0649f2379b125.png','作为同级平台，其运行数据需接入中台，由中台完成数据汇聚、清洗与整合治理，形成农业用水统一视图。','1','1','0','吴同',2,TO_DATE('2025-09-18 15:27:27.078000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-18 15:27:27.078000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."ATT_CLIENT"("ID","NAME","TYPE","SECRET","HOMEPAGE_URL","ALLOW_URL","SYNC_URL","LOGO","DESCRIPTION","PUBLIC_FLAG","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(6,'电子证照系统','0','45ab41bbc4d24835995eac4d9417ae19',null,null,null,'/profile/2025/09/18/68cbb468e4b0649f2379b126.png','作为同级平台，中台从中拉取证照信息后进行标准化处理与关联治理，用于用户身份核验与材料免提交支撑。','1','1','0','吴同',2,TO_DATE('2025-09-18 15:27:37.713000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-18 15:27:37.713000','YYYY-MM-DD HH24:MI:SS.FF'),null);
INSERT INTO "QDATA"."ATT_CLIENT"("ID","NAME","TYPE","SECRET","HOMEPAGE_URL","ALLOW_URL","SYNC_URL","LOGO","DESCRIPTION","PUBLIC_FLAG","VALID_FLAG","DEL_FLAG","CREATE_BY","CREATOR_ID","CREATE_TIME","UPDATE_BY","UPDATER_ID","UPDATE_TIME","REMARK") VALUES(7,'某县水资源管理系统','0','048823249e6747a0bb6a7db92627a360',null,null,null,'/profile/2025/09/18/68cbb475e4b0649f2379b127.png','作为下级业务系统，需向数据中台定时上报取水许可、用水计划执行、重点取水户监测等数据，由中台统一汇聚、清洗与标准化治理，形成全域水资源管理数据视图。','1','1','0','吴同',2,TO_DATE('2025-09-18 15:27:50.453000','YYYY-MM-DD HH24:MI:SS.FF'),'吴同',2,TO_DATE('2025-09-18 15:27:50.453000','YYYY-MM-DD HH24:MI:SS.FF'),null);
