COMMENT ON TABLE "QDATA"."QRTZ_PAUSED_TRIGGER_GRPS" IS '暂停的触发器表';

COMMENT ON COLUMN "QDATA"."QRTZ_PAUSED_TRIGGER_GRPS"."SCHED_NAME" IS '调度名称';

COMMENT ON COLUMN "QDATA"."QRTZ_PAUSED_TRIGGER_GRPS"."TRIGGER_GROUP" IS 'qrtz_triggers表trigger_group的外键';

COMMENT ON TABLE "QDATA"."QRTZ_SCHEDULER_STATE" IS '调度器状态表';

COMMENT ON COLUMN "QDATA"."QRTZ_SCHEDULER_STATE"."SCHED_NAME" IS '调度名称';

COMMENT ON COLUMN "QDATA"."QRTZ_SCHEDULER_STATE"."INSTANCE_NAME" IS '实例名称';

COMMENT ON COLUMN "QDATA"."QRTZ_SCHEDULER_STATE"."LAST_CHECKIN_TIME" IS '上次检查时间';

COMMENT ON COLUMN "QDATA"."QRTZ_SCHEDULER_STATE"."CHECKIN_INTERVAL" IS '检查间隔时间';

COMMENT ON TABLE "QDATA"."QRTZ_SIMPLE_TRIGGERS" IS '简单触发器的信息表';

COMMENT ON COLUMN "QDATA"."QRTZ_SIMPLE_TRIGGERS"."SCHED_NAME" IS '调度名称';

COMMENT ON COLUMN "QDATA"."QRTZ_SIMPLE_TRIGGERS"."TRIGGER_NAME" IS 'qrtz_triggers表trigger_name的外键';

COMMENT ON COLUMN "QDATA"."QRTZ_SIMPLE_TRIGGERS"."TRIGGER_GROUP" IS 'qrtz_triggers表trigger_group的外键';

COMMENT ON COLUMN "QDATA"."QRTZ_SIMPLE_TRIGGERS"."REPEAT_COUNT" IS '重复的次数统计';

